// 사람마다 처리 시간 p[i]. 각자 기다린 시간(자기 차례가 끝날 때까지)의 합
sort(p, p + n);                            // 짧은 사람부터
int t = 0, sum = 0;
for (int i = 0; i < n; i++) {
    t += p[i];                             // i번째 사람이 끝나는 시각
    sum += t;
}

